CREATE FUNCTION public.validate_content_record() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF jsonb_typeof(NEW.data)<>'object' THEN RAISE EXCEPTION 'Content details must be an object.'; END IF; IF NEW.kind='slideshow' THEN IF COALESCE(NEW.data->>'cta_destination','') NOT IN ('/','/about','/eye-care','/doctors','/facilities','/gallery','/testimonials','/contact','/contact#appointment') THEN RAISE EXCEPTION 'Choose a valid website destination.'; END IF; IF NEW.published AND (NEW.image_id IS NULL OR length(COALESCE(NEW.data->>'cta_label',''))=0) THEN RAISE EXCEPTION 'Published slides need a photo and CTA text.'; END IF; END IF; IF NEW.kind='gallery' AND NEW.image_id IS NULL THEN RAISE EXCEPTION 'Gallery items need a photo.'; END IF; IF NEW.kind='testimonials' AND (NEW.data->>'rating') IS NOT NULL AND (NEW.data->>'rating')::numeric NOT BETWEEN 0 AND 5 THEN RAISE EXCEPTION 'Ratings must be between 0 and 5.'; END IF; IF NEW.kind='youtube' AND COALESCE(NEW.data->>'video_id','') !~ '^[A-Za-z0-9_-]{11}$' THEN RAISE EXCEPTION 'Enter a valid YouTube video ID.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_content BEFORE INSERT OR UPDATE ON public.content FOR EACH ROW EXECUTE FUNCTION public.validate_content_record();
CREATE TABLE public.booking_abuse_limits (key text PRIMARY KEY, window_started timestamptz NOT NULL DEFAULT now(), attempts integer NOT NULL DEFAULT 1);
GRANT ALL ON public.booking_abuse_limits TO service_role;
ALTER TABLE public.booking_abuse_limits ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.check_booking_limit(_key text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN INSERT INTO public.booking_abuse_limits(key) VALUES(_key) ON CONFLICT(key) DO UPDATE SET attempts=CASE WHEN booking_abuse_limits.window_started<now()-interval '1 hour' THEN 1 ELSE booking_abuse_limits.attempts+1 END,window_started=CASE WHEN booking_abuse_limits.window_started<now()-interval '1 hour' THEN now() ELSE booking_abuse_limits.window_started END RETURNING attempts INTO n; RETURN n<=20; END $$;
REVOKE ALL ON FUNCTION public.check_booking_limit(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.check_booking_limit(text) TO service_role;